mapper.insert:
INSERT INTO public.user_info (
      user_id
    , company_code
    , division_code
    , dept_name
    , password
    , emp_no
    , name_kor
    , name_eng
    , name_local
    , position_name
    , position_name_eng
    , email
    , cell_phone_no
    , office_phone_no
    , fax_no
    , status
    , user_auth
    , default_language
    , sso_yn
    , create_date
    , create_by
    , update_date
    , update_by
    , work_yyyy_mm
) VALUES (
      #{user_id}
    , #{company_code}
    , #{division_code}
    , #{dept_name}
    , #{password}
    , #{emp_no}
    , #{name_kor}
    , #{name_eng}
    , #{name_local}
    , #{position_name}
    , #{position_name_eng}
    , #{email}
    , #{cell_phone_no}
    , #{office_phone_no}
    , #{fax_no}
    , #{status}
    , #{user_auth}
    , #{default_language}
    , #{sso_yn}
    , now()
    , #{create_by}
    , now()
    , #{update_by}
    , to_char(current_date, 'YYYY-MM')
)

