UPDATE user_info SET emp_no = #{emp_no}, name_kor = #{name_kor}, name_eng = #{name_eng}, dept_name = #{dept_name}, position_name = #{position_name}, position_name_eng = #{position_name_eng}, email = #{email}, office_phone_no = #{office_phone_no}, cell_phone_no = #{cell_phone_no}, fax_no = #{fax_no}, default_language = #{default_language}, status = #{status}, update_date = NOW(), update_by = #{update_by}
, password = #{password}
WHERE user_id = #{user_id}

UPDATE signature
   SET real_file    = #{real_file,jdbcType=BINARY},
       sign_file_name = #{sign_file_name}
 WHERE seq = ${seq}

