mapper.update:
UPDATE signature
   SET end_date        = replace(#{end_date},'-', ''),
       remark          = #{remark},
       update_date     = NOW(),
       update_by       = #{update_by}
 WHERE seq = ${seq}

mapper.select:
SELECT COUNT(*) FILTER (where hs_code is not null and trim(hs_code) != '') as hs_code_exists_count, COUNT(*) FILTER (where hs_code is null or trim(hs_code) = '') as hs_code_missing_count FROM ( SELECT DISTINCT im.item_code, im.hs_code FROM item_mst im JOIN item_dtl id ON im.item_code = id.item_code AND im.company_code = id.company_code JOIN division di ON id.division_code = di.division_code AND id.company_code = di.company_code LEFT join product_line pl ON im.company_code = pl.company_code AND im.product_code = pl.product_code LEFT join code_dtl cd ON id.company_code = cd.company_code AND id.assets_type = cd.code AND cd.category = 'AT' WHERE im.delete_yn = 'N' AND im.company_code = #{company_code}
AND di.division_code = #{search_division_code}
AND (im.hs_code IS NULL OR TRIM(im.hs_code) = '')
AND UPPER(im.item_code) LIKE '%' || UPPER(#{serch_keyword}) || '%'
AND ( UPPER(im.item_name) LIKE '%' || UPPER(#{serch_keyword}) || '%' OR UPPER(im.item_name_eng) LIKE '%' || UPPER(#{serch_keyword}) || '%' )
AND UPPER(im.hs_code) LIKE '%' || UPPER(#{serch_keyword}) || '%'
) t

