UPDATE customer_model
   SET customer_hs_code   = #{customer_hs_code}
     , customer_item_code = #{customer_item_code}
     , customer_item_name = #{customer_item_name}
     , customer_standard  = #{customer_standard}
     , remark             = #{remark}
     , update_date        = now()
     , update_by          = #{user_id}
 WHERE company_code  = #{company_code}
   AND division_code = #{division_code}
   AND item_code     = #{item_code}
   AND customer_code = #{customer_code}

