    , customer_item_name
    , customer_standard
    , remark
    , create_date
    , create_by
    , update_date
    , update_by
) VALUES (
      #{company_code}
    , #{division_code}
    , #{item_code}
    , #{customer_code}
    , #{customer_hs_code}
    , #{customer_item_code}
    , #{customer_item_name}
    , #{customer_standard}
    , #{remark}
    , now()
    , #{user_id}
    , now()
    , #{user_id}
